import { execSync } from "node:child_process";
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

export const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
export const SAMPLES = path.join(ROOT, "public", "samples");
export const FIXTURES = path.join(ROOT, "tests", "fixtures");

let ensured = false;
/** The demo files are generated by `npm run samples`; generate them if a fresh checkout doesn't have them yet. */
export function ensureSamples() {
  if (ensured) return;
  const needed = [
    path.join(SAMPLES, "History"),
    path.join(SAMPLES, "BrowserHistory.json"),
    path.join(SAMPLES, "chatgpt-conversations.json"),
    path.join(SAMPLES, "characterai-transcript.txt"),
    path.join(FIXTURES, "places.sqlite"),
    path.join(FIXTURES, "History.db"),
    path.join(FIXTURES, "expected.json"),
  ];
  if (needed.some((f) => !fs.existsSync(f))) {
    execSync("npm run samples", { cwd: ROOT, stdio: "inherit" });
  }
  ensured = true;
}

export function readBytes(file: string): Uint8Array {
  ensureSamples();
  return new Uint8Array(fs.readFileSync(file));
}

export function readText(file: string): string {
  ensureSamples();
  return fs.readFileSync(file, "utf8");
}

export function enc(text: string): Uint8Array {
  return new TextEncoder().encode(text);
}

export function expected(): {
  chrome: { visits: number; uniqueUrls: number; firstTs: number; lastTs: number };
  takeout: { visits: number };
  firefox: { visits: number; firstUrl: string; firstTs: number };
  safari: { visits: number; firstUrl: string; firstTs: number };
  chatgpt: { conversations: number };
} {
  ensureSamples();
  return JSON.parse(fs.readFileSync(path.join(FIXTURES, "expected.json"), "utf8"));
}
